CREATE TABLE IF NOT EXISTS crypto_liquidation_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),exchange_id text NOT NULL REFERENCES crypto_exchanges(id),market_id text NOT NULL REFERENCES crypto_markets(id),asset_id text NOT NULL REFERENCES crypto_assets(id),source_record_id text NOT NULL,side text NOT NULL CHECK(side IN('LONG','SHORT')),price numeric(38,18) NOT NULL CHECK(price>0),quantity numeric(38,18) NOT NULL CHECK(quantity>0),notional numeric(38,18) NOT NULL CHECK(notional>0),observed_at timestamptz NOT NULL,known_at timestamptz NOT NULL DEFAULT now(),source text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(exchange_id,source_record_id));
CREATE INDEX IF NOT EXISTS crypto_liquidation_events_market_time_idx ON crypto_liquidation_events(market_id,observed_at);
CREATE TABLE IF NOT EXISTS crypto_liquidation_aggregates(market_id text NOT NULL REFERENCES crypto_markets(id),interval text NOT NULL CHECK(interval IN('5m','1h','4h','1d')),bucket_at timestamptz NOT NULL,total_notional numeric(38,18) NOT NULL,long_notional numeric(38,18) NOT NULL,short_notional numeric(38,18) NOT NULL,largest_notional numeric(38,18) NOT NULL,event_count integer NOT NULL,source text NOT NULL,known_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(market_id,interval,bucket_at));
